// ============================================================
// app.js — Configuración de Express
// Solo configura middlewares y rutas. NO arranca el servidor.
// El servidor se inicia en server.js para facilitar testing.
// ============================================================

import express    from 'express';
import morgan     from 'morgan';
import path       from 'path';
import { fileURLToPath } from 'url';
import router     from './routes/index.js';
import oficialDetalleRoutes from './routes/oficialDetalleRoutes.js';
import { notFound }    from './middlewares/notFound.js';
import { errorHandler } from './middlewares/errorHandler.js';
import Database from 'better-sqlite3';

const app = express();
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const rootDir = path.resolve(__dirname, '..');

const sqlitePath = path.join(rootDir, 'data', 'oficiales.db');

const getDatabase = () => {
  const db = new Database(sqlitePath);
  db.pragma('foreign_keys = ON');
  return db;
};

const officerListQuery = `
  SELECT o.id, o.cedula, o.nombres, o.apellidos, o.sexo, o.telefono_movil,
         p.rango, p.estatus_actual, p.credencial_unica, p.fecha_ingreso,
         p.nivel_academico, p.especialidades
  FROM oficiales o
  LEFT JOIN datos_profesionales p ON p.oficial_id = o.id
  ORDER BY o.id DESC
`;

// ── Middlewares globales ──────────────────────────────────────
app.use(morgan('dev'));
app.use(express.json());
app.use(express.urlencoded({ extended: false }));
app.use(express.static(path.join(rootDir, 'public')));

// ── Motor de vistas ──────────────────────────────────────────
app.set('views', path.join(rootDir, 'views'));
app.set('view engine', 'ejs');

// ── Rutas ────────────────────────────────────────────────────
app.use('/api', router);
app.use('/expedientes-completo', oficialDetalleRoutes);

// Ruta raíz de bienvenida
app.get('/', (req, res) => {
  res.render('index', {
    title: 'Registro Institucional de Oficiales'
  });
});

app.get('/registrar', (req, res) => {
  res.render('registrar', { title: 'Registrar Oficial' });
});

